"""Real generic table calls, value-copy Get and const query APIs."""
CORE=r'''
#include <type_traits>
template<class K,class V> json hashRun7(const json& row){const auto& args=row["arguments"];int capacity=args[1].get<int>();auto keys=args[3].get<std::vector<K>>();auto values=args[4].get<std::vector<V>>();HashTable<K,V> actor(capacity),other(capacity);const HashTable<K,V>& readonly=actor;static_assert(std::is_same_v<decltype(actor.Put(std::declval<const K&>(),std::declval<const V&>())),void>);static_assert(std::is_same_v<std::decay_t<decltype(readonly.Get(std::declval<const K&>()))>,V>);static_assert(std::is_same_v<decltype(actor.Remove(std::declval<const K&>())),bool>);static_assert(std::is_same_v<decltype(readonly.Contains(std::declval<const K&>())),bool>);other.Put(keys[0],values[0]);if(readonly.Contains(keys[0]))throw std::runtime_error("New table instances own independent empty state");json results=json::array({nullptr});std::vector<K> seen;const auto& operations=args[2];for(size_t i=1;i<operations.size();++i){const K& key=keys[i];if(std::find(seen.begin(),seen.end(),key)==seen.end())seen.push_back(key);std::string operation=operations[i];json result;if(operation=="Put"){actor.Put(key,values[i]);result=nullptr;}else if(operation=="Get"){try{V value=readonly.Get(key);result=value;}catch(const std::out_of_range&){result=json{{"error","missing"}};}}else if(operation=="Remove")result=actor.Remove(key);else if(operation=="Contains")result=readonly.Contains(key);else throw std::runtime_error("Unknown operation");results.push_back(result);}auto entries=json::array();for(const K& key:seen){try{V value=readonly.Get(key);entries.push_back(json::array({key,value}));}catch(const std::out_of_range&){}}return json{{"actual",{{"results",results},{"finalEntries",entries}}},{"mutationOk",true}};}
json executeHash7(const json& row){return row["arguments"][0]=="text-number"?hashRun7<std::string,int>(row):hashRun7<int,std::string>(row);}
'''
